package com.sunrise.dentalclinic.service;
import com.sunrise.dentalclinic.exception.BusinessException; import com.sunrise.dentalclinic.model.Bill; import com.sunrise.dentalclinic.repository.BillRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.concurrent.ThreadLocalRandom;
@Service public class BillingService { private final BillRepository repo;private final AppointmentService appointments;private final BigDecimal fee;
 public BillingService(BillRepository r,AppointmentService a,@Value("${clinic.consultation-fee:1000.00}") BigDecimal f){repo=r;appointments=a;fee=f.setScale(2,RoundingMode.HALF_UP);}
 @Transactional public Bill generate(String appointmentNumber){var a=appointments.byNumber(appointmentNumber);if(repo.existsByAppointmentId(a.getId()))throw new BusinessException("A bill already exists for this appointment");var b=new Bill();b.setBillNumber(nextNumber());b.setAppointment(a);var cost=a.getTreatment().getTreatmentCost().setScale(2,RoundingMode.HALF_UP);b.setTreatmentCost(cost);b.setConsultationFee(fee);b.setTotalAmount(calculateTotal(cost,fee));return repo.save(b);}
 public BigDecimal calculateTotal(BigDecimal cost,BigDecimal consultation){return cost.add(consultation).setScale(2,RoundingMode.HALF_UP);}
 @Transactional(readOnly=true) public Bill get(Long id){return repo.findById(id).orElseThrow(()->new com.sunrise.dentalclinic.exception.ResourceNotFoundException("Bill not found"));}
 private String nextNumber(){for(int i=0;i<20;i++){var n="BIL-"+LocalDate.now().format(DateTimeFormatter.BASIC_ISO_DATE)+"-"+String.format("%05d",ThreadLocalRandom.current().nextInt(100000));if(!repo.existsByBillNumber(n))return n;}throw new BusinessException("Could not generate bill number; please retry");}}
